<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import HeinrichHeroBanner from '@/components/heinrich/HeinrichHeroBanner.vue';
import HeinrichStageRenderer from '@/components/heinrich/HeinrichStageRenderer.vue';
import UiModal from '@/components/shared/UiModal.vue';
import UiParentCard from '@/components/shared/UiParentCard.vue';
import { useRegistroPostulanteStore } from '@/stores/registroPostulante';
import { convocatorias, refreshConvocatorias } from '@/features/convocatorias/convocatorias.services';
import { admissionFor, ensureApplicantAdmissions, moveApplicantStage } from '../solicitudes-postulantes.services';
import { nombreCompleto } from '@/features/postulantes/postulantes.helpers';
const router = useRouter(); const route = useRoute(); const store = useRegistroPostulanteStore(); const active = ref('stage'); const changing = ref(false); const destination = ref<string | null>(null); const observation = ref(''); const notice = ref(false);
const postulanteId = computed(() => Number(route.params.postulanteId)); const registro = computed(() => store.registros.find(item => item.postulanteId === postulanteId.value)); const admission = computed(() => admissionFor(postulanteId.value)); const convocatoria = computed(() => convocatorias.value.find(item => item.id === admission.value?.convocatoriaId)); const stage = computed(() => convocatoria.value?.etapas.find(item => item.id === admission.value?.etapaActualId));
// Demo navigation supports configured outbound connections and their inverse so
// reviewers can move back through a path without changing its configuration.
const destinations = computed(() => (convocatoria.value?.etapas || []).filter(item => item.id !== stage.value?.id && (stage.value?.connectionIds?.includes(item.id) || item.connectionIds?.includes(stage.value?.id || '')))); const nombre = computed(() => registro.value ? nombreCompleto(registro.value.postulante) : 'Postulante');
onMounted(async () => { refreshConvocatorias(); await store.cargarRegistro(); const call = convocatorias.value.find(item => item.etapas.length) || convocatorias.value[0]; if (call) ensureApplicantAdmissions(store.registros, call.id, call.etapas); if (!registro.value) router.replace({ name: 'admision-postulantes' }); });
function changeStage() { if (!destination.value || !destinations.value.some(item => item.id === destination.value)) return; if (moveApplicantStage(postulanteId.value, destination.value, observation.value)) { changing.value = false; destination.value = null; observation.value = ''; notice.value = true; } }
</script>
<template><section><v-btn variant="text" class="px-0 mb-4" prepend-icon="mdi-arrow-left" @click="router.push({ name: 'admision-postulantes' })">Volver a postulantes</v-btn><HeinrichHeroBanner :title="nombre" :subtitle="convocatoria?.nombre || 'Postulante'" /><UiParentCard title="Información del postulante" icon="mdi-account-outline" class="mb-6"><v-row><v-col cols="12" md="4"><b>Convocatoria</b><div>{{ convocatoria?.nombre || '—' }}</div></v-col><v-col cols="12" md="4"><b>Nivel / grado</b><div>{{ convocatoria?.grado || convocatoria?.nivel || '—' }}</div></v-col><v-col cols="12" md="4"><b>Etapa actual</b><div>{{ stage?.nombre || '—' }}</div></v-col></v-row></UiParentCard><UiParentCard><v-tabs v-model="active"><v-tab value="stage">Etapa actual</v-tab><v-tab value="registration">Registro</v-tab><v-tab value="history">Historial</v-tab></v-tabs><v-divider class="mb-5" /><div v-if="active === 'stage'"><div class="d-flex justify-space-between align-start mb-4"><div><div class="text-h6">{{ stage?.nombre }}</div><div class="text-body-2 text-medium-emphasis">{{ stage?.descripcion }}</div></div><v-btn color="primary" :disabled="!destinations.length" @click="changing = true">Cambiar etapa</v-btn></div><v-alert v-if="!destinations.length" type="info" variant="tonal" density="compact" class="mb-4">No existen etapas destino configuradas para la etapa actual.</v-alert><HeinrichStageRenderer v-if="stage && admission" :stage="stage" :postulante-id="postulanteId" :data="admission.respuestas" mode="readonly" /></div><div v-else-if="active === 'registration' && registro"><UiParentCard title="Datos del postulante" icon="mdi-account-outline" class="mb-4"><v-row><v-col cols="12" md="6"><b>Nombre</b><div>{{ nombre }}</div></v-col><v-col cols="12" md="6"><b>Documento</b><div>{{ registro?.postulante.documentoIdentidad || '—' }}</div></v-col><v-col cols="12" md="6"><b>Fecha de nacimiento</b><div>{{ registro?.postulante.fechaNacimiento || '—' }}</div></v-col></v-row></UiParentCard><UiParentCard title="Tutor responsable" icon="mdi-account-star-outline" class="mb-4"><div>{{ registro && nombreCompleto(registro.tutorPrincipal) }}</div><div class="text-body-2 text-medium-emphasis">{{ registro?.tutorPrincipal.correoElectronico || 'Sin correo' }} · {{ registro?.tutorPrincipal.telefonoCelular || 'Sin teléfono' }}</div></UiParentCard><UiParentCard title="Tutores vinculados" icon="mdi-account-group-outline" class="mb-4"><div>{{ registro && nombreCompleto(registro.tutorSegundo) }}</div></UiParentCard><UiParentCard title="Grupo familiar" icon="mdi-home-group-outline"><v-list density="compact"><v-list-item v-for="sibling in store.registros.filter(item => item.postulanteId !== registro?.postulanteId && item.tutorPrincipalId === registro?.tutorPrincipalId)" :key="sibling.postulanteId" :title="nombreCompleto(sibling.postulante)" /></v-list></UiParentCard></div><div v-else><v-timeline side="end" density="compact"><v-timeline-item v-for="entry in admission?.historial || []" :key="`${entry.fecha}-${entry.destinoId}`" dot-color="primary"><div class="font-weight-medium">{{ convocatoria?.etapas.find(item => item.id === entry.destinoId)?.nombre || 'Etapa' }}</div><div class="text-caption text-medium-emphasis">{{ new Date(entry.fecha).toLocaleString() }} · {{ entry.responsable || '—' }}</div><div v-if="entry.observacion" class="text-body-2">{{ entry.observacion }}</div></v-timeline-item></v-timeline></div></UiParentCard><UiModal :show="changing" title="Cambiar etapa" subtitle="Selecciona la etapa a la que deseas mover al postulante." persistent @update:show="changing = false"><p><b>Postulante:</b> {{ nombre }}<br><b>Etapa actual:</b> {{ stage?.nombre }}</p><v-select v-model="destination" :items="destinations" item-title="nombre" item-value="id" label="Etapa destino *" /><v-textarea v-model="observation" label="Observación" rows="2" auto-grow /><template #footer-actions><v-btn variant="text" @click="changing = false">Cancelar</v-btn><v-btn color="primary" :disabled="!destination" @click="changeStage">Confirmar cambio</v-btn></template></UiModal><v-snackbar v-model="notice" color="success">Etapa actualizada y movimiento registrado.</v-snackbar></section></template>
